INSERT INTO langs (Id, French) VALUES (9110000, 'Os de Scalarcin'),
 (9110001, 'Chez les Scalarcin, il est courant de perdre les os.'),
 (9110002, 'Dent de Marzwel'),
 (9110003, 'Est-ce que la petite sousouris passera pendant votre sommeil, même si c''est la dent de quelqu''un d''autre ? Il faut essayer pour le savoir.'),
 (9110004, 'Rouage de Qil Bil'),
 (9110005, 'Ce rouage n''est rien sans d''autres rouages, il fait partie d''un tout. Mais lorsqu''il est à sa place, il fonctionne avec une efficacité inébranlable. De plus il émet un son reconnaissable même dans le plus profond des ghettos : Ratatata.'),
 (9110006, 'Griffe de Tyranne'),
 (9110007, 'Cette griffe a sûrement déchiqueté plus de gens que n''avez eu d''amis dans toute votre vie.'),
 (9110008, 'Joyau des Scalptaras'),
 (9110009, 'Ce joyau aurait la particularité d''aider son détenteur à ne plus entendre les petites voix dans sa tête. Son efficacité reste à démontrer...'),
 (9110010, 'Globe oculaire de Musha'),
 (9110011, 'On dit que Musha peut manger sans faim. C''est dû au fait que son œil semble directement relié à son estomac. C''est donc ça, avoir l''œil plus gros que le ventre ?'),
 (9110012, 'Poil de Simbadas'),
 (9110013, 'Ce poil turquoise est bien plus doux que celui d''un mufafah, mais lorsque vous verrez la gueule de Simbadas s''ouvrir pour vous arracher un bras, ce n''est pas le détail que vous retiendrez.'),
 (9110014, 'Dent en or de Rok Gnorok'),
 (9110015, 'L''or a toujours été un investissement stable et fructueux. Avec l''augmentation récente de sa valeur, Rok Gnorok a dû faire attention à tous les aventuriers avides ayant une dent contre lui.'),
 (9110016, 'Poudre à canon de Carlita'),
 (9110017, 'Cette poudre à canon peut être très explosive : c''est de la bonne.'),
 (9110018, 'Cheveux de Naganita'),
 (9110019, 'En lui arrachant une touffe de cheveux, vous avez fait un sale coup à Naganita. Elle en sera quitte pour faire irruption dans le salon de coiffure le plus proche afin d''exiger des coups de ciseaux réparateurs.'),
 (9110020, 'Pic de Trukipik'),
 (9110021, 'Ce truc pique.'),
 (9110022, 'Fleur de Nenufor Tilotus'),
 (9110023, 'Cette fleur a la particularité de s''ouvrir dès qu''elle est posée sur l''eau, embaumant les étangs d''une fragrance capiteuse. En d''autres termes, le Tilotus, il sent fort.'),
 (9110024, 'Moelle de Demoël'),
 (9110025, 'Les Demoël ont été formels à ce sujet, ils sont totalement contre le don de leur moelle. Pas de greffe, pas de grief.'),
 (9110026, 'Langue de Fojumo'),
 (9110027, 'Il semblerait qu''il n''y avait pas de barrière à cette langue.'),
 (9110028, 'Sang du Shushu Debruk''Sayl'),
 (9110029, 'Apparemment, certaines personnes auraient préféré boire ce liquide poisseux plutôt que de manger un chou. Difficile de les blâmer.'),
 (9110030, 'Scalp de Predagob'),
 (9110031, 'Oui, c''est horrible, mais il vous aurait fait la même chose si vous n''étiez pas sorti victorieux de cet affrontement.'),
 (9110032, 'Coffre d''Ogivol Scalarcin'),
 (9110033, 'Ce coffre contient un trésor inestimable.'),
